#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// Minimal JSON token helpers for judge input ["s","p"]
static char* extract_string(const char* line, int* pos) {
    int i = *pos;
    while (line[i] && line[i] != '"') i++;
    if (!line[i]) return NULL;
    i++; // skip opening quote
    int start = i;
    while (line[i] && line[i] != '"') i++;
    int len = i - start;
    char* out = (char*)malloc(len + 1);
    strncpy(out, line + start, len);
    out[len] = '\0';
    if (line[i] == '"') i++;
    *pos = i;
    return out;
}

bool isMatch(const char* s, const char* p) {
    int m = (int)strlen(s);
    int n = (int)strlen(p);
    bool **dp = (bool**)malloc((m + 1) * sizeof(bool*));
    for (int i = 0; i <= m; ++i) {
        dp[i] = (bool*)calloc(n + 1, sizeof(bool));
    }
    dp[m][n] = true;
    for (int j = n - 2; j >= 0; --j) if (p[j + 1] == '*') dp[m][j] = dp[m][j + 2];
    for (int i = m - 1; i >= 0; --i) {
        for (int j = n - 1; j >= 0; --j) {
            bool firstMatch = (p[j] == '.' || p[j] == s[i]);
            if (j + 1 < n && p[j + 1] == '*') dp[i][j] = dp[i][j + 2] || (firstMatch && dp[i + 1][j]);
            else dp[i][j] = firstMatch && dp[i + 1][j + 1];
        }
    }
    bool ans = dp[0][n];
    for (int i = 0; i <= m; ++i) free(dp[i]);
    free(dp);
    return ans;
}

