        if (line == null) return;
        line = line.trim();
        if (line.isEmpty()) return;
        // Expect JSON array [s, p]
        String[] parts = line.replaceAll("^\[|\]$", "").split(",(?=\")");
        String s = parts[0].trim();
        String p = parts[1].trim();
        s = s.replaceAll("^\"|\"$", "");
        p = p.replaceAll("^\"|\"$", "");
        System.out.println(isMatch(s, p));
    }
}

